-- Australia deep-dive page translations: page fields, stats, cards,
-- lifecycle card + statuses, steps, portal.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Peppol descentralizado de 4 esquinas', 'Esta página de análisis refleja la orientación técnica disponible públicamente a julio de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. Los programas a nivel estatal, los objetivos de automatización de las NCE y cualquier futuro debate sobre un mandato B2B continúan evolucionando — confirme los requisitos actuales directamente con la ATO antes de construir una integración.', 'Todavía no existe un mandato B2B general en Australia — pero el gobierno federal ha construido discretamente un régimen de cumplimiento interno genuinamente exigente para sus propios organismos.', 'PINT A-NZ es una especificación compartida — constrúyala una vez y será conforme tanto en Australia como en Nueva Zelanda.', 'Una implementación Peppol de cuatro esquinas de manual — sin autoridad de compensación, sin plataforma gubernamental central para el B2B.', 'Todavía no hay ningún mandato para el que registrarse fuera del suministro al gobierno — pero la vía de incorporación es idéntica tanto si se está preparando voluntariamente como si abastece a un organismo federal.', 'No existe un régimen de sanciones legal para el B2B, ya que no existe ningún mandato B2B — pero la trayectoria es clara.' FROM countries WHERE name_en = 'Australia';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Dezentrales 4-Ecken-Peppol-Modell', 'Diese Länderanalyse spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Landesweite Programme, NCE-Automatisierungsziele und jede künftige Diskussion über eine B2B-Pflicht entwickeln sich weiter — bestätigen Sie aktuelle Anforderungen direkt bei der ATO, bevor Sie eine Integration aufbauen.', 'Es besteht in Australien immer noch keine allgemeine B2B-Pflicht — aber die Bundesregierung hat still ein wirklich anspruchsvolles internes Compliance-Regime für ihre eigenen Behörden aufgebaut.', 'PINT A-NZ ist eine gemeinsame Spezifikation — einmal umgesetzt, sind Sie sowohl in Australien als auch in Neuseeland konform.', 'Eine lehrbuchmäßige Vier-Ecken-Peppol-Implementierung — keine Clearing-Behörde, keine zentrale Regierungsplattform für B2B.', 'Es gibt außerhalb der Regierungslieferung noch keine Pflicht, für die man sich registrieren müsste — aber der Onboarding-Weg ist identisch, egal ob Sie sich freiwillig vorbereiten oder eine Bundesbehörde beliefern.', 'Für B2B besteht kein gesetzliches Bußgeldregime, da keine B2B-Pflicht existiert — aber die Richtung ist klar.' FROM countries WHERE name_en = 'Australia';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Peppol décentralisé à 4 coins', 'Cette analyse par pays reflète les directives techniques publiquement disponibles à juillet 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Les programmes au niveau des États, les objectifs d''automatisation des NCE et toute discussion future sur une obligation B2B continuent d''évoluer — confirmez les exigences actuelles directement auprès de l''ATO avant de construire une intégration.', 'Il n''existe toujours pas d''obligation B2B générale en Australie — mais le gouvernement fédéral a discrètement mis en place un régime de conformité interne véritablement exigeant pour ses propres agences.', 'PINT A-NZ est une spécification partagée — construisez une seule fois, et vous êtes conforme à la fois en Australie et en Nouvelle-Zélande.', 'Une mise en œuvre Peppol à quatre coins conforme au manuel — aucune autorité de contrôle, aucune plateforme gouvernementale centrale pour le B2B.', 'Il n''y a encore aucune obligation à laquelle s''inscrire en dehors de l''approvisionnement du gouvernement — mais le parcours d''intégration est identique, que vous vous prépariez volontairement ou que vous approvisionniez une agence fédérale.', 'Aucun régime de sanctions légal n''existe pour le B2B, puisqu''aucune obligation B2B n''existe — mais la trajectoire est claire.' FROM countries WHERE name_en = 'Australia';

