INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Especificación', '[["Formato actual", "PINT A-NZ Billing Process (v1.1.2)"], ["Estándar base", "Metodología Peppol International (PINT), UBL"], ["Sustituido", "A-NZ Peppol BIS Billing 3.0 (eliminado el 15 de mayo de 2025)"]]', 'PINT A-NZ también se alinea con mercados Peppol más recientes como Singapur, Malasia y Japón — un paso genuino hacia una mayor interoperabilidad en Asia-Pacífico, no solo un ejercicio exclusivo de Australia/NZ.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Spezifikation', '[["Aktuelles Format", "PINT A-NZ Billing Process (v1.1.2)"], ["Basisstandard", "Peppol-International-Methodik (PINT), UBL"], ["Abgelöst", "A-NZ Peppol BIS Billing 3.0 (entfernt am 15. Mai 2025)"]]', 'PINT A-NZ ist zudem an neuere Peppol-Märkte wie Singapur, Malaysia und Japan angeglichen — ein echter Schritt hin zu breiterer Interoperabilität im asiatisch-pazifischen Raum, nicht nur eine reine Australien-/NZ-Übung.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Spécification', '[["Format actuel", "PINT A-NZ Billing Process (v1.1.2)"], ["Norme de base", "Méthodologie Peppol International (PINT), UBL"], ["Remplacé", "A-NZ Peppol BIS Billing 3.0 (retiré le 15 mai 2025)"]]', 'PINT A-NZ s''aligne également sur des marchés Peppol plus récents comme Singapour, la Malaisie et le Japon — une réelle avancée vers une interopérabilité plus large en Asie-Pacifique, pas un simple exercice propre à l''Australie/NZ.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Localización para el GST', '[["Adaptado para", "Requisitos de GST de Australia y Nueva Zelanda"], ["Tipo de documento", "XML UBL 2.1, legible por máquina de principio a fin"]]', 'Todo campo de datos de factura obligatorio de la ATO se transporta en una estructura estandarizada que cualquier sistema contable conectado a Peppol puede procesar automáticamente — sin reintroducción manual de datos.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Lokalisierung für GST', '[["Angepasst für", "GST-Anforderungen Australiens und Neuseelands"], ["Dokumenttyp", "UBL-2.1-XML, durchgängig maschinenlesbar"]]', 'Jedes von der ATO vorgeschriebene Rechnungsdatenfeld wird in einer standardisierten Struktur übertragen, die jedes Peppol-angebundene Buchhaltungssystem automatisch verarbeiten kann — ohne manuelle Neueingabe.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Localisation pour la TPS', '[["Adapté pour", "Les exigences de TPS de l''Australie et de la Nouvelle-Zélande"], ["Type de document", "XML UBL 2.1, lisible par machine de bout en bout"]]', 'Chaque champ de données de facture obligatoire de l''ATO est transporté dans une structure normalisée que tout système comptable connecté à Peppol peut traiter automatiquement — sans ressaisie manuelle.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Autofacturación', '[["Especificación", "A-NZ Self-billing Process v1.1.2"], ["Estado", "Opcional para que los proveedores de servicios la admitan"]]', 'Mismo modelo de datos subyacente que la facturación PINT A-NZ estándar, pero con los roles de emisor/receptor invertidos — consulte con su Punto de Acceso si la admite antes de depender de ella.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Selbstfakturierung', '[["Spezifikation", "A-NZ Self-billing Process v1.1.2"], ["Status", "Für Dienstanbieter optional zu unterstützen"]]', 'Gleiches zugrunde liegendes Datenmodell wie die Standard-PINT-A-NZ-Rechnungsstellung, jedoch mit vertauschten Sender-/Empfängerrollen — prüfen Sie bei Ihrem Access Point, ob dies unterstützt wird, bevor Sie sich darauf verlassen.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Autofacturation', '[["Spécification", "A-NZ Self-billing Process v1.1.2"], ["Statut", "Optionnel pour les prestataires de services"]]', 'Même modèle de données sous-jacent que la facturation PINT A-NZ standard, mais avec les rôles émetteur/destinataire inversés — vérifiez auprès de votre Access Point s''il le prend en charge avant de vous y fier.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Lo que sigue siendo voluntario', '[["Facturación electrónica B2B", "Voluntaria, bajo el Business e-Invoicing Right (BER)"]]', 'El BER permite a una empresa elegible solicitar la capacidad de facturación electrónica a sus socios comerciales — un mecanismo de incentivo más que un mandato legal, útil de conocer si un cliente le pide que cambie.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Was weiterhin freiwillig ist', '[["B2B-E-Rechnung", "Freiwillig, im Rahmen des Business e-Invoicing Right (BER)"]]', 'Das BER erlaubt es einem berechtigten Unternehmen, von Handelspartnern die Fähigkeit zur E-Rechnung einzufordern — ein Anstoßmechanismus statt einer gesetzlichen Pflicht, gut zu wissen, falls ein Kunde Sie zum Wechsel auffordert.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Ce qui reste volontaire', '[["Facturation électronique B2B", "Volontaire, dans le cadre du Business e-Invoicing Right (BER)"]]', 'Le BER permet à une entreprise éligible de demander à ses partenaires commerciaux la capacité de facturation électronique — un mécanisme d''incitation plutôt qu''une obligation légale, utile à connaître si un client vous demande de basculer.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Gobernanza', '[["Autoridad Peppol nacional", "Oficina de Impuestos de Australia (ATO)"], ["Función", "Acredita a los proveedores de Puntos de Acceso y de servicios SMP"]]', 'El papel de la ATO aquí es la supervisión regulatoria de la red, no operar una plataforma de compensación — nunca ve el contenido de su factura directamente.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Governance', '[["Nationale Peppol-Behörde", "Australisches Finanzamt (ATO)"], ["Rolle", "Akkreditiert Access-Point- und SMP-Dienstanbieter"]]', 'Die Rolle der ATO besteht hier in der regulatorischen Aufsicht über das Netzwerk, nicht im Betrieb einer Clearing-Plattform — sie sieht Ihren Rechnungsinhalt nie direkt.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Gouvernance', '[["Autorité Peppol nationale", "Administration fiscale australienne (ATO)"], ["Rôle", "Accrédite les prestataires Access Point et SMP"]]', 'Le rôle de l''ATO ici est une supervision réglementaire du réseau, pas l''exploitation d''une plateforme de contrôle — elle ne voit jamais directement le contenu de votre facture.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Obligaciones específicas de las NCE', '[["Alcance", "Entidades del Commonwealth No Corporativas"], ["Objetivo 2026", "30 % de las facturas recibidas vía Peppol"], ["Reporte", "Trimestral a la Autoridad Peppol de Australia"]]', 'Si abastece a organismos federales australianos, espere que impulsen activamente la adopción de Peppol durante este período — condiciones de pago más rápidas son el incentivo práctico ofrecido.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'NCE-spezifische Pflichten', '[["Umfang", "Non-Corporate Commonwealth Entities"], ["Ziel 2026", "30 % der eingegangenen Rechnungen über Peppol"], ["Berichterstattung", "Vierteljährlich an die australische Peppol-Behörde"]]', 'Wenn Sie australische Bundesbehörden beliefern, erwarten Sie, dass diese in diesem Zeitraum aktiv auf die Peppol-Einführung drängen — schnellere Zahlungsbedingungen sind der praktische Anreiz.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Obligations propres aux NCE', '[["Périmètre", "Non-Corporate Commonwealth Entities"], ["Objectif 2026", "30 % des factures reçues via Peppol"], ["Déclaration", "Trimestrielle à l''autorité Peppol australienne"]]', 'Si vous fournissez des agences fédérales australiennes, attendez-vous à ce qu''elles poussent activement vers l''adoption de Peppol durant cette période — des conditions de paiement plus rapides constituent l''incitation pratique proposée.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Variación a nivel estatal', '[["Federal", "Recepción B2G obligatoria desde 2022"], ["Estados", "Varios gestionan sus propios programas de adopción independientes"]]', 'No dé por sentada una única norma nacional a nivel estatal — compruebe los propios requisitos de facturación electrónica de su cliente gubernamental estatal específico junto con el marco federal.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Unterschiede auf Bundesstaatenebene', '[["Bundesebene", "B2G-Empfangspflicht seit 2022"], ["Bundesstaaten", "Mehrere betreiben eigene, separate Einführungsprogramme"]]', 'Gehen Sie nicht von einer einheitlichen nationalen Regelung auf Bundesstaatenebene aus — prüfen Sie die eigenen E-Rechnungsanforderungen Ihres spezifischen Landesregierungskunden zusätzlich zum bundesweiten Rahmen.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Variation au niveau des États', '[["Fédéral", "Réception B2G obligatoire depuis 2022"], ["États", "Plusieurs gèrent leurs propres programmes d''adoption distincts"]]', 'Ne présumez pas d''une règle nationale unique au niveau des États — vérifiez les propres exigences de facturation électronique de votre client gouvernemental d''État spécifique en plus du cadre fédéral.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'es', 'Las cuatro esquinas', 'Cada factura pasa por la misma secuencia:', 'Las Respuestas a Nivel de Mensaje (MLR) proporcionan notificaciones de estado estructuradas — aceptado, rechazado, entregado o fallido — ofreciendo una trazabilidad completa a lo largo del intercambio.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Australia';
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'de', 'Die vier Ecken', 'Jede Rechnung durchläuft dieselbe Abfolge:', 'Message Level Responses (MLRs) liefern strukturierte Statusbenachrichtigungen — angenommen, abgelehnt, zugestellt oder fehlgeschlagen — und sorgen für vollständige Nachvollziehbarkeit über den gesamten Austausch.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Australia';
INSERT OR IGNORE INTO deep_dive_lifecycle_card_translations (card_id, lang, title, intro_text, outro_text) SELECT dlc.id, 'fr', 'Les quatre coins', 'Chaque facture suit la même séquence :', 'Les Message Level Responses (MLR) fournissent des notifications d''état structurées — acceptée, rejetée, livrée ou échouée — offrant une traçabilité complète tout au long de l''échange.' FROM deep_dive_lifecycle_cards dlc JOIN countries c ON c.id = dlc.country_id WHERE c.name_en = 'Australia';

