INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🔄 El sentido de la trayectoria', NULL, NULL, 'Entre el impulso de automatización de las NCE, la expansión de los programas estatales y el Business e-Invoicing Right, Australia avanza de manera constante hacia una adopción obligatoria más amplia sin haberse comprometido formalmente todavía a un mandato B2B universal.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🔄 Die Entwicklungsrichtung', NULL, NULL, 'Zwischen dem NCE-Automatisierungsschub, wachsenden Bundesstaatenprogrammen und dem Business e-Invoicing Right bewegt sich Australien stetig auf eine breitere verpflichtende Einführung zu, ohne sich bislang formell auf eine universelle B2B-Pflicht festgelegt zu haben.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🔄 Le sens de l''évolution', NULL, NULL, 'Entre la poussée d''automatisation des NCE, l''expansion des programmes des États et le Business e-Invoicing Right, l''Australie progresse régulièrement vers une adoption obligatoire plus large, sans s''être encore formellement engagée dans une obligation B2B universelle.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '💳 El pago más rápido como incentivo real', NULL, NULL, 'En lugar de sanciones, el enfoque de Australia se apoya en incentivos: las facturas electrónicas conformes a organismos gubernamentales se pagan más rápido según la política de condiciones de pago vigente — una razón comercial para cambiar incluso sin un requisito legal.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '💳 Schnellere Zahlung als echter Anreiz', NULL, NULL, 'Statt auf Strafen setzt Australiens Ansatz auf Anreize: konforme E-Rechnungen an Regierungsbehörden werden im Rahmen der bestehenden Zahlungsbedingungspolitik schneller bezahlt — ein kommerzieller Grund zum Wechsel auch ohne gesetzliche Pflicht.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '💳 Un paiement plus rapide comme véritable incitation', NULL, NULL, 'Plutôt que sur des sanctions, l''approche australienne s''appuie sur des incitations : les factures électroniques conformes envoyées aux agences gouvernementales sont payées plus rapidement selon la politique de conditions de paiement existante — une raison commerciale de basculer même sans obligation légale.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🇳🇿 Alineación transtasmania', NULL, NULL, 'Como Australia y Nueva Zelanda comparten PINT A-NZ, una única implementación de integración sirve para ambos mercados — genuinamente útil si comercia a través del mar de Tasmania.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🇳🇿 Abstimmung über die Tasmanische See hinweg', NULL, NULL, 'Da Australien und Neuseeland PINT A-NZ gemeinsam nutzen, deckt ein einziger Integrationsaufbau beide Märkte ab — wirklich nützlich, wenn Sie über die Tasmanische See hinweg Handel treiben.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🇳🇿 Alignement transtasmanien', NULL, NULL, 'Comme l''Australie et la Nouvelle-Zélande partagent PINT A-NZ, une seule intégration construite sert les deux marchés — véritablement utile si vous commercez à travers la mer de Tasman.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '📶 Compatibilidad global con Peppol', NULL, NULL, 'La alineación de PINT A-NZ con mercados Peppol más recientes (Singapur, Malasia, Japón) significa que la inversión en cumplimiento aquí también facilita la facturación transfronteriza hacia esos mercados.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '📶 Globale Peppol-Kompatibilität', NULL, NULL, 'Die Ausrichtung von PINT A-NZ an neueren Peppol-Märkten (Singapur, Malaysia, Japan) bedeutet, dass die hier getätigte Compliance-Investition auch die grenzüberschreitende Rechnungsstellung in diese Märkte erleichtert.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'penalties_related' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '📶 Compatibilité Peppol mondiale', NULL, NULL, 'L''alignement de PINT A-NZ sur des marchés Peppol plus récents (Singapour, Malaisie, Japon) signifie que l''investissement en conformité réalisé ici facilite également la facturation transfrontalière vers ces marchés.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Australia' AND dc.section = 'penalties_related' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Elija un Punto de Acceso Peppol acreditado por la ATO', 'Seleccione un proveedor certificado — muchas plataformas contables australianas convencionales ya incluyen esta conectividad integrada.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Australia' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wählen Sie einen von der ATO akkreditierten Peppol Access Point', 'Wählen Sie einen zertifizierten Anbieter — viele gängige australische Buchhaltungsplattformen enthalten diese Konnektivität bereits standardmäßig.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Australia' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Choisissez un Access Point Peppol accrédité par l''ATO', 'Sélectionnez un prestataire certifié — de nombreuses plateformes comptables australiennes courantes intègrent déjà cette connectivité.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Australia' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Registre su ID de participante Peppol', 'Esto le hace localizable en la red para que cualquier socio comercial conectado a Peppol pueda enrutarle facturas.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Australia' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Registrieren Sie Ihre Peppol-Teilnehmer-ID', 'Dadurch werden Sie im Netzwerk auffindbar, sodass jeder Peppol-angebundene Handelspartner Rechnungen an Sie weiterleiten kann.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Australia' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Enregistrez votre identifiant participant Peppol', 'Cela vous rend repérable sur le réseau afin que tout partenaire commercial connecté à Peppol puisse vous acheminer des factures.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Australia' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme que su ERP genera XML PINT A-NZ válido', 'Pruebe con la especificación actual v1.1.2 — cualquier cosa que todavía apunte al antiguo perfil A-NZ BIS 3.0 ya no se aceptará en ningún punto de la red.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Australia' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie, dass Ihr ERP gültiges PINT-A-NZ-XML erzeugt', 'Testen Sie gegen die aktuelle Spezifikation v1.1.2 — alles, was noch auf das alte A-NZ-BIS-3.0-Profil abzielt, wird nirgendwo mehr im Netzwerk akzeptiert.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Australia' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Confirmez que votre ERP génère du XML PINT A-NZ valide', 'Testez par rapport à la spécification actuelle v1.1.2 — tout ce qui vise encore l''ancien profil A-NZ BIS 3.0 ne sera plus accepté nulle part sur le réseau.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Australia' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Si abastece a organismos federales, prepárese para el impulso de 2026', 'Espere un fomento activo (e incentivos de pago más rápido) para pasar a Peppol a medida que las NCE avanzan hacia su objetivo del 30 %.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Australia' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wenn Sie Bundesbehörden beliefern, bereiten Sie sich auf den Schub 2026 vor', 'Rechnen Sie mit aktiver Ermutigung (und schnelleren Zahlungsanreizen), auf Peppol umzusteigen, während NCEs auf ihr 30-%-Ziel hinarbeiten.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Australia' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Si vous fournissez des agences fédérales, préparez-vous à la poussée de 2026', 'Attendez-vous à un encouragement actif (et à des incitations de paiement plus rapide) à passer à Peppol à mesure que les NCE progressent vers leur objectif de 30 %.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Australia' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Compruebe por separado cualquier requisito específico de cada estado', 'Si abastece a clientes del gobierno estatal, confirme el calendario de su propio programa de adopción junto con el marco federal.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Australia' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Prüfen Sie etwaige bundesstaatsspezifische Anforderungen separat', 'Wenn Sie Landesregierungskunden beliefern, bestätigen Sie deren eigenen Zeitplan für die Einführung zusätzlich zum bundesweiten Rahmen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Australia' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Vérifiez séparément toute exigence propre à un État', 'Si vous fournissez des clients gouvernementaux d''État, vérifiez le calendrier de leur propre programme d''adoption en plus du cadre fédéral.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Australia' AND ds.sort_order = 4;

